def sop_html(s):
    h=_b(s);i=s['id'];ul=lambda a:'<ul>'+''.join(f'<li>{E(x)}</li>' for x in a)+'</ul>'
    for a,c,e in (('Security configuration','sec','🔐'),('Production considerations','prod','🏭'),('Troubleshooting','ts','🛠'),('Rollback and cleanup','warn','⚠️')):
        h=h.replace(f'<details><summary>{a}</summary>',f'<details class="co co-{c}"><summary>{e} {a}</summary>')
    pre=''
    if i in WARN:pre+=f'<div class="co co-warn"><b>⚠️ Warning</b> {E(WARN[i])}</div>'
    if i in COST:pre+=f'<div class="co co-cost"><b>💰 Cost</b> {E(COST[i])}</div>'
    h=h.replace('<h3>Procedure</h3>',pre+'<h3>Procedure</h3>',1)
    if i in REC:h=h.replace('<details class="co co-sec">','<h3>Recommended configuration</h3>'+ul(REC[i])+'<details class="co co-sec">',1)
    rel=''.join(f'<a href="#sop-{x}">{E(_T[x])}</a>' for x in REL.get(i,'').split() if x in _T)
    tail='<h3>Best practices ('+s['cat']+')</h3>'+ul(BP.get(s['cat'],'').split('|'))+('<h3>Related services</h3><div class="chips">'+rel+'</div>' if rel else '')
    return h.replace('<h3>Validation checklist</h3>',tail+'<h3>Validation checklist</h3>',1)
